import hashlib
import hmac

SECRET = b"ctf-secret"
POINTS = {"warmup": 10, "login": 50}

def make_flag(name):
    return "CTF{" + hmac.new(SECRET, name.encode("utf-8"), "sha256").hexdigest()[:12] + "}"

STORED = {name: hashlib.sha256(make_flag(name).encode("utf-8")).hexdigest() for name in POINTS}

def check(name, submission):
    if name not in STORED:
        return False
    digest = hashlib.sha256(submission.encode("utf-8")).hexdigest()
    return hmac.compare_digest(digest, STORED[name])

scores = {}
solved = {}
n = int(input())
for _ in range(n):
    team, name, sub = input().split()
    if name in solved.get(team, set()):
        continue
    if check(name, sub):
        solved.setdefault(team, set()).add(name)
        scores[team] = scores.get(team, 0) + POINTS[name]
for team in sorted(scores, key=lambda t: (-scores[t], t)):
    print(team + " " + str(scores[team]))
